// "Nexus Code" — API routes for the repo-editing feature. See the plan section
// "Nexus Code — Nexus édite le repo GitHub d'un utilisateur" for the full design.
//
// Session tokens are single-use links generated by the /editrepo Discord command and stored in
// Firestore directly (bypassing dashboard/server/db.js's SQL-emulation layer, which is shaped
// around guild config and not a good fit for this) — possession of the unguessable token is the
// entire authorization mechanism for v1, there is no dashboard user auth to check against.
import express from 'express';
import { firestoreDb } from '../../../src/utils/firestoreDatabase.js';
import { nexusClient } from '../../../src/services/nexusAiService.js';
import { proposeEdit, applyEdit, rejectEdit, getPendingRequest } from '../services/repoEditService.js';

const router = express.Router();

const SESSION_PREFIX = 'codeedit:session:';

// The Discord bot's own startup (src/app.js) normally connects firestoreDb before this router
// ever sees a request in production. This guard makes the route self-sufficient even if the
// dashboard is ever run standalone (no bot token, so that startup path never runs) — connect()
// is a cheap no-op when already connected.
async function ensureFirestore() {
  if (!firestoreDb.isAvailable()) {
    await firestoreDb.connect().catch(() => false);
  }
}

async function loadSession(token) {
  if (!token || typeof token !== 'string') return null;
  await ensureFirestore();
  return firestoreDb.get(`${SESSION_PREFIX}${token}`, null);
}

async function saveSession(token, session) {
  // ttl is re-applied every save so an in-progress session doesn't expire mid-review; it's
  // capped by the 15-min window set when the token was first created either way.
  const remainingSeconds = Math.max(60, Math.round((session.expiresAt - Date.now()) / 1000));
  await firestoreDb.set(`${SESSION_PREFIX}${token}`, session, remainingSeconds);
}

/**
 * Asks the real Nexus AI engine to rewrite one file. Uses askCodeEdit (code-architect persona +
 * nexus-12b via the codeEditRequest flag — see server.ts) rather than askJSON/askNexusAi, since
 * this needs the raw modified file content back, not a conversational answer.
 */
async function generateEdit(oldContent, filePath, instruction) {
  const prompt =
    `Given this file's exact current content (path: ${filePath}), apply the following instruction ` +
    `and output ONLY the complete modified file content — no markdown fences, no explanation, ` +
    `nothing before or after the file content.\n\n` +
    `Instruction: ${instruction}\n\n` +
    `--- Current file content ---\n${oldContent}\n--- End of file ---`;
  const result = await nexusClient.askCodeEdit({ prompt });
  // askCodeEdit resolves to the plain response string (see nexus-ai.js) — strip accidental
  // markdown fences defensively in case the model wraps the file anyway.
  const text = typeof result === 'string' ? result : (result?.response || result?.text || '');
  return text.replace(/^```[\w-]*\n?/, '').replace(/```\s*$/, '').trim() + '\n';
}

router.get('/session/:token', async (req, res) => {
  const session = await loadSession(req.params.token);
  if (!session) {
    return res.status(404).json({ error: 'This link is invalid or has expired.' });
  }
  if (session.expiresAt < Date.now()) {
    return res.status(410).json({ error: 'This link has expired — run /editrepo again on Discord.' });
  }
  if (session.used) {
    return res.status(410).json({ error: 'This link has already been used.' });
  }
  res.json({ valid: true, discordUsername: session.discordUsername || null });
});

router.post('/session/:token/propose', async (req, res) => {
  const { token } = req.params;
  const session = await loadSession(token);
  if (!session) return res.status(404).json({ error: 'This link is invalid or has expired.' });
  if (session.expiresAt < Date.now()) return res.status(410).json({ error: 'This link has expired.' });
  if (session.used) return res.status(410).json({ error: 'This link has already been used.' });

  const { repoUrl, filePath, instruction, githubToken } = req.body || {};
  if (!githubToken || typeof githubToken !== 'string') {
    return res.status(400).json({ error: 'A GitHub token is required.' });
  }

  try {
    const result = await proposeEdit({ repoUrl, filePath, instruction, githubToken, generateEdit });
    session.used = true; // one proposal per link — a fresh /editrepo is required to try again
    session.requestId = result.requestId;
    await saveSession(token, session);
    res.json(result);
  } catch (err) {
    if (err.code === 'BUSY') {
      return res.status(409).json({ error: err.message });
    }
    res.status(400).json({ error: err.message || 'Something went wrong proposing this edit.' });
  }
});

router.post('/session/:token/apply', async (req, res) => {
  const { token } = req.params;
  const session = await loadSession(token);
  const { requestId, githubToken } = req.body || {};

  if (!session || session.requestId !== requestId) {
    return res.status(404).json({ error: 'This proposed change is no longer available.' });
  }
  if (!githubToken || typeof githubToken !== 'string') {
    return res.status(400).json({ error: 'A GitHub token is required to push.' });
  }
  if (!getPendingRequest(requestId)) {
    return res.status(410).json({ error: 'This proposed change has expired — start over with /editrepo.' });
  }

  try {
    const result = await applyEdit({ requestId, githubToken });
    res.json(result);
  } catch (err) {
    res.status(400).json({ error: err.message || 'Something went wrong applying this edit.' });
  }
});

router.post('/session/:token/cancel', async (req, res) => {
  const { requestId } = req.body || {};
  if (requestId) await rejectEdit(requestId);
  res.json({ ok: true });
});

export default router;
